// SYS10-R2 browser capture over HTTP (portable dist-http build).
// CONTROLLED FIXTURE: the save below is generated by the real engine, but the L2 Workbench, refinery,
// salvaged oil, glass and wood stock are injected here. Counts only as controlled UI evidence (below S3).
import {chromium} from 'playwright';import {createServer} from 'vite';import {mkdir,writeFile} from 'node:fs/promises';import assert from 'node:assert/strict';
const dir='../evidence/sys10-r2';await mkdir(`${dir}/frames`,{recursive:true});
const vite=await createServer({configFile:'vite.config.ts',server:{middlewareMode:true,hmr:false},appType:'custom'});
const E=await vite.ssrLoadModule('/src/game/engine.ts');const P=await vite.ssrLoadModule('/src/game/persist.ts');const K=await vite.ssrLoadModule('/src/game/core.ts');
const {newGame,dispatch,addItem,C,countItem,mkContainer,stepStations,markDirty}=E;const {serializeSnapshot,validate}=P;const {TILE}=K;
const T=Date.UTC(2026,10,6);const log=[];
const g=newGame();assert(dispatch(g,{id:'r2-start',type:'startRun',character:'female',seed:77},T).ok,'startRun');
const r=g.run,p=r.player;
const act=(type,payload,id)=>{const res=dispatch(g,{id,type,...payload},T+100);log.push({intent:type,id,ok:res.ok,reason:res.reason??null,receipt:res.receipt??null});return res;};
const f=mkContainer(r,'fuel',3),o=mkContainer(r,'out',6);
r.entities['fixture-bench']={id:'fixture-bench',kind:'struct',type:'workbench',x:p.x+TILE,y:p.y,tx:Math.floor(p.x/TILE)+1,ty:Math.floor(p.y/TILE),hp:160,maxHp:160,station:{fuelC:f.id,outC:o.id,burn:0,queue:[],level:2}};
for(const [k,q] of [['iron_ingot',4],['mechanical_parts',3],['spares',5],['brick',6],['glass',3],['salvaged_oil',6]])addItem(r,'inv',k,q);
const built=act('build',{struct:'refinery',tx:Math.floor(p.x/TILE)-1,ty:Math.floor(p.y/TILE)},'r2-build');assert(built.ok,'build '+built.reason);
const ref=Object.values(r.entities).find(e=>e.type==='refinery');addItem(r,ref.station.fuelC,'wood',3);
const cr=act('craft',{recipe:'refinery_industrial',eid:ref.id},'r2-craft');assert(cr.ok,'craft '+cr.reason);
const save=serializeSnapshot(g);assert(validate(JSON.parse(JSON.parse(save).payload)),'valid save');
await writeFile(`${dir}/controlled-fixture-save.json`,save);
await writeFile(`${dir}/engine-intents.json`,JSON.stringify({seed:77,disclosure:'controlled fixture: L2 workbench, refinery placed by real build intent (no cabinet), 6 oil + 3 glass + 3 wood injected',refineryId:ref.id,intents:log},null,2));
await vite.close();
const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/tmp/chromium',args:['--no-sandbox']});
const shots=[];
try{
 const ctx=await browser.newContext({viewport:{width:640,height:360}});
 await ctx.addInitScript(({save})=>{if(!localStorage.getItem('soh.state.v3'))localStorage.setItem('soh.state.v3',save);},{save});
 const page=await ctx.newPage();
 await page.goto(process.env.SOH_URL||'http://localhost:8765/index.html',{waitUntil:'load'});
 await page.waitForTimeout(2000);
 await page.screenshot({path:`${dir}/frames/01-title-640x360.png`});shots.push('01-title');
 // Real input: click the Continue button on the title screen.
 await page.getByRole('button',{name:/Continue/}).first().click();
 await page.waitForTimeout(2500);
 const canvases=await page.locator('canvas').count();
 await page.screenshot({path:`${dir}/frames/02-after-continue-640x360.png`});shots.push('02-after-continue');
 await page.keyboard.press('f');await page.waitForTimeout(1500);
 await page.screenshot({path:`${dir}/frames/03-after-F-interact-640x360.png`});shots.push('03-after-F-interact');
 const info=await page.evaluate(()=>({title:document.title,canvases:[...document.querySelectorAll('canvas')].map(c=>({w:c.width,h:c.height,cw:c.clientWidth,ch:c.clientHeight}))}));
 await writeFile(`${dir}/browser-log.json`,JSON.stringify({url:page.url(),canvases,info,shots,consoleNote:'real clicks: Continue only; world interaction not yet driven'},null,2));
 console.log('OK canvases',canvases);
}finally{await browser.close();}
